/** Tin nhạy cảm (nhắc nhở, vắng học, ghi chép) không hiện nội dung trên màn hình khoá, trừ khi người dùng cho phép. */
export function pushMessage(n: ClaimedNotification, sub: Pick<ClaimedSub, 'shared'>): PushMessage {
  const hide = n.sensitive && !n.showSensitive;
  let title = hide ? 'OPEN-EDU: có thông tin mới' : n.title;
  const body = hide ? 'Mở ứng dụng để xem chi tiết.' : n.body;
  if (sub.shared && n.name) title = `${n.name} · ${title}`;
  return {
    title: title.slice(0, 120),
    body: body.slice(0, 240),
    link: n.link && n.link.startsWith('/') ? n.link : '/',
    tag: n.tag,
    kind: n.kind,
    badge: Math.max(0, Math.floor(n.badge || 0)),
  };
}
